import { NgTemplateOutlet } from '@angular/common';
import { ChangeDetectionStrategy, Component, computed, input, model, output } from '@angular/core';
import { RouterLink, RouterLinkActive } from '@angular/router';

/**
 * Item de navegação do rail.
 *
 * O consumidor fornece a lista completa; o componente apenas renderiza e emite.
 * A ausência de `position` é tratada como `main` para simplificar o uso comum.
 */
export interface PakiNavigationRailItem {
  /** Identificador emitido em `itemSelected`; deve ser único na lista. */
  id: string;
  /** Nome exibido e usado como nome acessível no estado recolhido. */
  label: string;
  /** Rota opcional; quando presente, o item navega via RouterLink. */
  route?: string;
  /** Classe CSS do ícone; os glifos ficam a cargo da aplicação consumidora. */
  icon?: string;
  /** Quando verdadeiro, o item não navega e não emite `itemSelected`. */
  disabled?: boolean;
  /** Agrupa o item no topo (`main`) ou ancorado ao rodapé (`footer`). */
  position?: 'main' | 'footer';
}

/**
 * Cabeçalho de marca do rail.
 *
 * Sem `route` o cabeçalho não é navegável, por simetria com os itens.
 */
export interface PakiNavigationRailBrand {
  /** Texto da marca exibido no cabeçalho. */
  label: string;
  /** Rota opcional; quando presente, o cabeçalho navega ao ser acionado. */
  route?: string;
}

/**
 * Faixa de navegação vertical recolhível, acessível e temática.
 *
 * Entrega estados recolhido (64px) e expandido (216px) por two-way
 * `expanded`/`expandedChange`, itens com rota opcional, item de rodapé e
 * cabeçalho de marca. O componente não persiste estado; a decisão de
 * persistência é do consumidor.
 */
@Component({
  selector: 'paki-navigation-rail',
  standalone: true,
  // RouterLink e RouterLinkActive dão navegação e destaque de rota ativa aos
  // itens com rota. NgTemplateOutlet reaproveita a mesma semântica de item nos
  // grupos main e footer sem duplicar o markup.
  imports: [NgTemplateOutlet, RouterLink, RouterLinkActive],
  templateUrl: './paki-navigation-rail.html',
  styleUrl: './paki-navigation-rail.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    '[class.paki-navigation-rail--expanded]': 'expanded()',
  },
})
export class PakiNavigationRail {
  /** Estado recolhido/expandido controlado pelo consumidor; inicia recolhido. */
  readonly expanded = model(false);

  /** Lista de itens de navegação; padrão vazio evita erro em estado inicial. */
  readonly items = input<readonly PakiNavigationRailItem[]>([]);

  /** Cabeçalho de marca opcional. */
  readonly brand = input<PakiNavigationRailBrand | undefined>(undefined);

  /** Emite o `id` do item selecionado; suprimido quando o item é `disabled`. */
  readonly itemSelected = output<string>();

  /** Itens do grupo principal: `position` ausente conta como `main`. */
  readonly mainItems = computed(() =>
    this.items().filter((item) => item.position === undefined || item.position === 'main'),
  );

  /** Itens ancorados ao rodapé, separados visualmente do grupo principal. */
  readonly footerItems = computed(() =>
    this.items().filter((item) => item.position === 'footer'),
  );

  /**
   * Emite `itemSelected` com o `id` do item acionado.
   *
   * Serve aos itens com rota (`<a>`) e sem rota (`<button>`). O item `disabled`
   * usa um elemento não interativo sem este handler no template; por isso não
   * navega nem emite. A supressão em `disabled` vem da estrutura do template,
   * não deste método.
   *
   * @param item Item de navegação acionado pelo usuário.
   */
  onItemActivate(item: PakiNavigationRailItem): void {
    this.itemSelected.emit(item.id);
  }

  /**
   * Alterna o estado recolhido/expandido do rail.
   *
   * Inverte o valor de `expanded` (model), o que emite `expandedChange` com o
   * novo valor e atualiza a largura via classe de estado no host. Serve ao
   * controle de expansão nativo (`<button [attr.aria-expanded]>`) (FR-001,
   * FR-002, AC-001).
   */
  toggleExpanded(): void {
    this.expanded.update((value) => !value);
  }
}

styleUrlsData.data:
// Largura controlada por variável CSS local, alternada por classe de estado.
// As próximas tarefas adicionam tokens de tema, estilo de item ativo, divisor
// do rodapé e a regra de prefers-reduced-motion.
:host {
  display: block;
  height: 100%;
  // Estado recolhido padrão: 64px (NFR-005).
  --paki-navigation-rail-width: 64px;
}

:host(.paki-navigation-rail--expanded) {
  // Estado expandido: 216px (NFR-005).
  --paki-navigation-rail-width: 216px;
}

.paki-navigation-rail {
  background: var(--color-bg-surface);
  border-right: 1px solid var(--color-border-subtle);
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  // Anima a mudança de largura entre recolhido (64px) e expandido (216px).
  transition: width 200ms ease;
  width: var(--paki-navigation-rail-width);
}

// Respeita a preferência do usuário por menos movimento: suprime a transição
// de largura quando prefers-reduced-motion está ativo (NFR-003, AC-001).
@media (prefers-reduced-motion: reduce) {
  .paki-navigation-rail {
    transition: none;
  }
}

.paki-navigation-rail__list {
  display: grid;
  gap: 4px;
  list-style: none;
  margin: 0;
  padding: 8px;
}

.paki-navigation-rail__list--footer {
  // Ancora o grupo de rodapé na base do rail, separado dos itens principais.
  margin-top: auto;
  // Divisor visual entre o grupo principal e o rodapé (AC-005). Usa o token de
  // borda sutil do tema para manter contraste coerente nos temas claro e escuro.
  border-top: 1px solid var(--color-border-subtle);
}

// Cabeçalho de marca (AC-006). Separa a marca dos itens com um divisor sutil e
// alinha o conteúdo ao mesmo padding dos grupos de itens.
.paki-navigation-rail__brand {
  border-bottom: 1px solid var(--color-border-subtle);
  padding: 12px;
}

// Elemento da marca em ambos os casos (navegável ou não): mesma aparência
// tipográfica, sem sublinhado no link, com reticências quando o texto excede.
.paki-navigation-rail__brand-link,
.paki-navigation-rail__brand-label {
  color: var(--color-text-primary);
  display: block;
  font-weight: 600;
  overflow: hidden;
  text-decoration: none;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.paki-navigation-rail__item {
  display: block;
}

// Base comum aos três tipos de item (<a>, <button>, <span> disabled) para que
// a aparência não dependa do elemento HTML escolhido pela semântica.
.paki-navigation-rail__link {
  align-items: center;
  background: none;
  border: 0;
  border-radius: 8px;
  color: var(--color-text-secondary);
  cursor: pointer;
  display: flex;
  font: inherit;
  gap: 12px;
  padding: 8px 12px;
  text-align: left;
  text-decoration: none;
  width: 100%;
}

// Item de rota ativa: fundo accent-tint marca o estado ativo; o texto usa
// text-primary para garantir contraste WCAG 2.1 AA nos dois temas (R-B/R-C).
// O texto accent sobre accent-tint reprovava AA no tema escuro (3.59:1); o
// text-primary sobe o contraste bem acima de 4.5:1 mantendo o realce pelo fundo.
.paki-navigation-rail__link.active {
  background: var(--color-accent-tint);
  color: var(--color-text-primary);
}

// Foco visível por teclado nos controles focáveis (AC-010, FR-011, NFR-001).
// O outline usa a cor de acento do tema, o que garante contraste do indicador
// (WCAG 2.1 AA, 3:1) nos temas claro e escuro por ler o mesmo token. O offset
// separa o contorno da borda arredondada. Restringe a :focus-visible para não
// exibir o outline em cliques de ponteiro.
.paki-navigation-rail__link:focus-visible,
.paki-navigation-rail__toggle:focus-visible,
.paki-navigation-rail__brand-link:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

// Item desabilitado: aparência esmaecida e sem interação de ponteiro.
.paki-navigation-rail__link--disabled {
  cursor: default;
  opacity: 0.5;
}

.paki-navigation-rail__label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

// Estado recolhido (padrão): esconde o rótulo textual; o nome acessível vem de
// aria-label e o tooltip de title (FR-008, AC-007). O ícone permanece visível.
// display:none também remove o texto da árvore de acessibilidade, restando só
// o ícone; por isso o nome acessível fica em aria-label no link.
:host(:not(.paki-navigation-rail--expanded)) .paki-navigation-rail__label {
  display: none;
}

// Controle de expansão: botão nativo focável, ancorado abaixo dos grupos.
.paki-navigation-rail__toggle {
  align-items: center;
  background: none;
  border: 0;
  border-radius: 8px;
  color: var(--color-text-secondary);
  cursor: pointer;
  display: flex;
  justify-content: center;
  margin: 8px;
  padding: 8px;
}

